 62	}
 63	/** Streaming prefix state is numeric only; no previous output chunk/tail is retained. */
 64	function outputWitness(){
 65	  const state:Record<string,number>={},counts:Record<string,number>={},observed:Record<string,number>={};
 66	  function observe(sink:string,chunk:unknown,encoding?:unknown):void {
 67	    const bytes=typeof chunk==='string'?Buffer.from(chunk,typeof encoding==='string'&&Buffer.isEncoding(encoding)?encoding:undefined):chunk instanceof Uint8Array?chunk:null;if(!bytes)return;observed[sink+'-calls']=(observed[sink+'-calls']??0)+1;observed[sink+'-bytes']=(observed[sink+'-bytes']??0)+bytes.byteLength;
 68	    for(const [label,value] of [['A',A],['B',B]] as const)for(const [variant,pattern] of encodings(value)){
 69	      const key=sink+'/'+label+'/'+variant;let matched=state[key]??0;
 70	      for(const byte of bytes){
 71	        while(matched>0&&byte!==pattern[matched]){let next=matched-1;while(next>0&&!pattern.subarray(0,next).equals(pattern.subarray(matched-next,matched)))next--;matched=next;}
 72	        if(byte===pattern[matched])matched++;
 73	        if(matched===pattern.length){counts[key]=(counts[key]??0)+1;matched=0;}
 74	      }state[key]=matched;
 75	    }
 76	  }
 77	  return {observe,counts,observed,hits:()=>Object.values(counts).reduce((total,n)=>total+n,0)};
 78	}
