 86	async function canaryScan(root:string):Promise<number>{
 87	  let hits=0;for(const entry of await readdir(root,{withFileTypes:true})){
 88	    const path=join(root,entry.name);if(entry.isDirectory())hits+=await canaryScan(path);
 89	    else if(entry.isFile())try{hits+=byteHits(await readFile(path));}catch(error){if(!(error instanceof Error&&'code' in error&&error.code==='ENOENT'))throw error;}
 90	  }return hits;
 91	}
