export async function launchGuidedBrowser(config: ObservationConfig, contextId: string, onLost: () => void): Promise<GuidedBrowser> {
  if (process.env.DEBUG || process.env.PWDEBUG || process.env.NODE_DEBUG || process.env.NODE_OPTIONS) throw new Error('DIAGNOSTICS_DENIED');
  const scratchDirectory = await mkdtemp(join(process.env.TMPDIR ?? tmpdir(), 'checks-guided-'));
  let context:BrowserContext|undefined;
  let preparedProfile=join(scratchDirectory,SCRATCH_SUBDIRECTORIES.profile);
  const disposeScratch=async():Promise<void>=>{releaseBrowserProfile(preparedProfile);await rm(scratchDirectory,{recursive:true,force:true});};
  try {
  const profile = prepareBrowserProfile(scratchDirectory);preparedProfile=profile;requireBrowserPreferences(profile);
  context = await chromium.launchPersistentContext(profile, { channel:'chromium',headless: true, chromiumSandbox: true, args: [], acceptDownloads: false, serviceWorkers: 'block', env: { PATH: process.env.PATH ?? '', HOME: process.env.HOME ?? '', TMPDIR: scratchDirectory } });
  const browser = context.browser();
  const page = context.pages()[0] ?? await context.newPage();
  const preferenceEvidence=await verifyBrowserPreferences(page,profile);
  let closed = false;
  context.on('page', extra => { if (extra !== page) { void extra.close().catch(() => undefined); onLost(); } });
